import{_ as n,l as s,o as e,c as i,v as t,p as d,x as o,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SCCP","description":"","frontmatter":{"title":"SCCP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sccp.md","filePath":"cs/sccp.md","lastUpdated":1789023840000}'),C={name:"cs/sccp.md"};function S(h,a,A,E,P,_){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="sccp" tabindex="-1">SCCP <a class="header-anchor" href="#sccp" aria-label="Permalink to &quot;SCCP&quot;">​</a></h1><div class="epigraph"><p>稀疏条件常量传播同时走 SSA 的 def-use 与 CFG 的可执行边：未执行的枝不产生常量冲突，于是更多名变成常量。</p><footer>—— 据 Wegman and Zadeck, Constant Propagation with Conditional Branches, 1991；Cytron SSA 论文对照整理</footer></div><p>上一课<a href="/cs/constant-propagation">常量传播</a>在「所有到达定值」上取交，死枝上的写仍会把格打成非常量。缺口是 <strong>SCCP</strong>：只沿可能执行的边传播，φ 只合并已执行前驱。本课钉工作表与可执行标志，不重写简单传播的折叠规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>if (1) x=2; else x=3;</code> 简单交得「非常量」，其实 \\(x=2\\)。SCCP：边先标不可执行，常量条件为真则只放行真枝。缺口是<strong>控制流与数据流联立</strong>，不是新的折叠表。</p><p>稀疏：用 SSA 的 use 链当工作表，不扫全部程序点。这与稀疏数据流家族一致。</p><h3 id="「可执行」是分析结论" tabindex="-1">「可执行」是分析结论 <a class="header-anchor" href="#「可执行」是分析结论" aria-label="Permalink to &quot;「可执行」是分析结论&quot;">​</a></h3><p>未访问边当不执行是可靠近似的一边：永远不把死枝当活。反面：条件未知则两边都活，退回简单传播。不要把 SCCP 当路径敏感的全部符号执行。</p><p><span class="marginnote">Wegman–Zadeck 1991（TOPLAS）。Clang/LLVM 的 SCCP/IPSCCP 是工程后裔。本课过程内；过程间是 IPSCCP，后课过程间分析点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>格：未定义 / 常量 / overdefined。工作表：SSA 边与 CFG 边。规则：操作数 overdefined 则结果 overdefined；常量则折；φ 忽略不可执行前驱。分支：条件为常量则只标记一侧边。</p>',11)),(e(),d(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SSA%5B%22SSA%20%2B%20CFG%22%5D%20--%3E%20WL%5B%22%E5%B7%A5%E4%BD%9C%E8%A1%A8%22%5D%0A%20%20WL%20--%3E%20EDGE%5B%22%E6%A0%87%E8%AE%B0%E5%8F%AF%E6%89%A7%E8%A1%8C%E8%BE%B9%22%5D%0A%20%20WL%20--%3E%20VAL%5B%22%E6%A0%BC%E4%B8%8A%E7%9A%84%E5%80%BC%22%5D%0A%20%20EDGE%20--%3E%20PHI%5B%22%CF%86%20%E5%8F%AA%E5%B9%B6%E6%B4%BB%E5%89%8D%E9%A9%B1%22%5D%0A%20%20VAL%20--%3E%20EDGE%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>实现：未定义与 overdefined 的次序要按论文：先当未定义，避免乐观错误。Wegman–Zadeck 给了格与初始化。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与死代码：不可执行块可删，但正式 ADCE 下一课。SCCP 露出的常量调用可能变成死参数。</p><p>过程间：若形参在所有活调用点是同一常量，可钉死——需调用图，后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写符号执行的路径爆炸。后课默认：条件常量用 SCCP。下一课 CSE/GVN：相等的是表达式，不只是立即数。</p><p>也不把 SCCP 当证明助手。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SCCP：可执行边 + SSA 稀疏传播。</li><li>死枝不参与 φ，精度高于简单交。</li><li>条件未知则两边都活。</li><li>出处：Wegman and Zadeck, 1991；对照 Cytron SSA、龙书常量传播。</li></ul>',9))])}const u=n(C,[["render",S]]);export{f as __pageData,u as default};
